import type { SVGProps } from "react";

export type MtnLogoProps = Omit<SVGProps<SVGSVGElement>, "type"> & {
  /** "color" (brand colors, automatic dark mode) or "mono" (currentColor). */
  variant?: "color" | "mono";
  /** "auto" swaps with your `.dark` class (Tailwind); "light" / "dark" force one file. */
  mode?: "auto" | "light" | "dark";
  /** Accessible name. Pass "" when the logo is decorative. */
  title?: string;
};

const join = (...classes: (string | undefined)[]) => classes.filter(Boolean).join(" ");

const Icon = (props: SVGProps<SVGSVGElement>) => <svg xmlns="http://www.w3.org/2000/svg" xmlSpace="preserve" viewBox="0 0 1280 640" {...props}><path d="M640 0C286.5 0 0 143.3 0 320s286.5 320 640 320 640-143.3 640-320S993.5 0 640 0m0 589.5C314.4 589.5 50.5 468.8 50.5 320S314.4 50.5 640 50.5s589.5 120.7 589.5 269.5S965.6 589.5 640 589.5m-80.7-325.6v-50.5h180.5v50.5h-65v162.8h-50.5V263.9zm398.5-50.6v213.3h-50.5l-91.6-127v127h-50.5V213.3h50.5l91.6 127v-127zM320.7 426.7V213.3h50.5l56.1 86.3 56.1-86.3H534v213.3h-50.5V306l-38.3 58.9h-35.6L371.2 306v120.7z" /></svg>;

const IconMono = (props: SVGProps<SVGSVGElement>) => <svg fill="currentColor" xmlns="http://www.w3.org/2000/svg" xmlSpace="preserve" viewBox="0 0 1280 640" {...props}><path d="M640 0C286.5 0 0 143.3 0 320s286.5 320 640 320 640-143.3 640-320S993.5 0 640 0m0 589.5C314.4 589.5 50.5 468.8 50.5 320S314.4 50.5 640 50.5s589.5 120.7 589.5 269.5S965.6 589.5 640 589.5m-80.7-325.6v-50.5h180.5v50.5h-65v162.8h-50.5V263.9zm398.5-50.6v213.3h-50.5l-91.6-127v127h-50.5V213.3h50.5l91.6 127v-127zM320.7 426.7V213.3h50.5l56.1 86.3 56.1-86.3H534v213.3h-50.5V306l-38.3 58.9h-35.6L371.2 306v120.7z" /></svg>;

const IconDark = (props: SVGProps<SVGSVGElement>) => <svg fill="#ffffff" xmlns="http://www.w3.org/2000/svg" xmlSpace="preserve" viewBox="0 0 1280 640" {...props}><path d="M640 0C286.5 0 0 143.3 0 320s286.5 320 640 320 640-143.3 640-320S993.5 0 640 0m0 589.5C314.4 589.5 50.5 468.8 50.5 320S314.4 50.5 640 50.5s589.5 120.7 589.5 269.5S965.6 589.5 640 589.5m-80.7-325.6v-50.5h180.5v50.5h-65v162.8h-50.5V263.9zm398.5-50.6v213.3h-50.5l-91.6-127v127h-50.5V213.3h50.5l91.6 127v-127zM320.7 426.7V213.3h50.5l56.1 86.3 56.1-86.3H534v213.3h-50.5V306l-38.3 58.9h-35.6L371.2 306v120.7z" /></svg>;

export function MtnLogo({
  variant = "color",
  mode = "auto",
  title = "MTN",
  className,
  ...props
}: MtnLogoProps) {
  const shared = {
    height: "1em",
    ...(title ? { role: "img", "aria-label": title } : { "aria-hidden": true }),
    ...props,
  } as SVGProps<SVGSVGElement>;

  if (variant === "mono") return <IconMono {...shared} className={className} />;

  return mode === "light" ? (
    <Icon {...shared} className={className} />
  ) : mode === "dark" ? (
    <IconDark {...shared} className={className} />
  ) : (
    <>
      <Icon {...shared} className={join(className, "dark:hidden")} />
      <IconDark {...shared} className={join(className, "hidden dark:block not-dark:hidden")} />
    </>
  );
}

export default MtnLogo;
